/* Canonical cascade migrated from audited historical sources; edit components here. */
*{box-sizing:border-box}
body{margin:0;color:var(--txt);font-family:Inter,system-ui,Segoe UI,Arial,sans-serif}
a{color:inherit;text-decoration:none}
html{scroll-behavior:smooth}
.topin{margin:auto;padding:10px 16px;display:flex;align-items:center;justify-content:space-between;gap:12px}
.brand{display:flex;align-items:center;gap:10px;font-weight:950}
.mark{width:36px;height:36px;background:linear-gradient(135deg,var(--cyan),#285ed8);color:#06101c;display:grid;place-items:center;box-shadow:0 10px 28px #0009}
.nav{display:flex;gap:8px;flex-wrap:wrap}
.nav a,.btn,button{border:1px solid var(--line);padding:9px 11px;font-size:13px;font-weight:820;color:#dcecff}
.btn.primary,button{border-color:var(--cyan);color:#04111b;cursor:pointer}
.shell{max-width:1220px;margin:auto;padding:18px 16px 96px}
.hero{padding:44px 0 24px;border-bottom:1px solid #16233a}
.hero.compact{padding-top:28px}
.client-hero{padding:34px 0 24px;border-bottom:1px solid #16233a;display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:16px;align-items:stretch}
.membership-card span{display:block;font-size:11px;color:var(--muted);font-weight:950;letter-spacing:.12em}
.membership-card strong{display:block;margin:8px 0;color:var(--cyan)}
.membership-card.plan-pro{border-color:#2b68ff;background:linear-gradient(180deg,#102b55,#0b111d)}
.membership-card.plan-pro strong{color:#72b8ff}
.membership-card.plan-elite,.membership-card.plan-admin{border-color:#8c6a25;background:linear-gradient(180deg,#3a2a0b,#0b111d)}
.membership-card.plan-elite strong,.membership-card.plan-admin strong{color:var(--gold)}
.app-hero{padding:34px 0 26px;border-bottom:1px solid #16233a;display:grid;grid-template-columns:minmax(0,1.35fr) minmax(280px,.65fr);gap:18px;align-items:end}
.kicker{font-size:12px;text-transform:uppercase}
h1{margin:10px 0 12px;letter-spacing:0;max-width:980px}
h2{font-size:24px;margin:0;letter-spacing:0}
.lead{max-width:860px;line-height:1.5}
.actions,.filters{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}
.admin-menu{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}
.quick-actions{display:grid;grid-template-columns:repeat(3,minmax(118px,1fr));gap:10px;margin-top:20px;max-width:720px}
.client-actions{max-width:none;grid-template-columns:repeat(auto-fit,minmax(138px,1fr))}
.quick{border:1px solid var(--line);background:#101827;border-radius:8px;padding:12px;display:flex;justify-content:space-between;align-items:center;min-height:58px}
.quick.primary{background:linear-gradient(135deg,var(--cyan),var(--green));color:#04111b;border-color:var(--cyan)}
.quick span{font-size:12px;font-weight:900;text-transform:uppercase;color:inherit}
.quick strong{font-size:24px}
.hero-panel{border:1px solid var(--line);border-radius:8px;background:linear-gradient(180deg,#122033,#0b111d);padding:14px}
.panel-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;font-weight:950}
.signal{display:grid;gap:6px;margin:12px 0;color:var(--muted);font-size:12px;font-weight:850}
.signal i,.momentum i{display:block;height:7px;background:linear-gradient(90deg,var(--cyan),var(--green));border-radius:999px}
.signal:after,.momentum{content:"";display:block;width:100%;height:7px;background:#1b2a40;border-radius:999px;overflow:hidden}
.momentum{margin-top:10px}
.filters{overflow:auto;padding:14px 0;margin-top:0}
.filters .btn{white-space:nowrap}
.live-strip{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;padding:12px 0;border-bottom:1px solid #16233a}
.live-strip div{border:1px solid var(--line);background:#101827;border-radius:8px;padding:11px;display:grid;gap:4px}
.live-strip span{font-size:11px;color:var(--muted);font-weight:900;text-transform:uppercase}
.live-strip strong{font-size:16px;color:var(--green)}
.band{padding:22px 0;border-bottom:1px solid #16233a}
.section-head{display:flex;justify-content:space-between;align-items:end;gap:12px}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(235px,1fr));gap:12px}
.compact-grid{grid-template-columns:repeat(auto-fit,minmax(180px,1fr))}
.two-col{display:grid;grid-template-columns:1fr 1fr;gap:14px}
.stack{display:grid;gap:10px}
.list-row{border:1px solid var(--line);background:#101827;border-radius:8px;padding:12px;display:flex;align-items:center;justify-content:space-between;gap:12px}
.list-row span{overflow:hidden;text-overflow:ellipsis}
.list-row strong{color:var(--green)}
.card{border:1px solid var(--line);background:linear-gradient(180deg,var(--panel),var(--panel2));border-radius:8px;min-height:104px}
.service-card{min-height:92px}
.match-card{position:relative}
.state-badge{display:inline-flex;align-items:center;border-radius:999px;padding:5px 8px;font-size:11px;font-weight:950;border:1px solid #33445f;background:#142033;color:#dcecff}
.state-badge.live{border-color:#2b8f62}
.state-badge.half{background:#342712;color:#ffd36c;border-color:#80601c}
.state-badge.done{background:#1b2636;color:#b9c9dc;border-color:#3a4b61}
.state-badge.suspended{background:#3a1722;color:#ff9ab0;border-color:#8b2a43}
.mini-link{display:inline-flex;margin-top:10px;color:var(--cyan);font-size:12px;font-weight:900}
.bottom-nav{display:none;position:fixed;left:10px;right:10px;bottom:10px;z-index:30;border:1px solid var(--line);background:#07101dee;backdrop-filter:blur(16px);border-radius:8px;padding:7px;grid-template-columns:repeat(auto-fit,minmax(52px,1fr));gap:6px;box-shadow:0 16px 40px #000b}
.bottom-nav a{display:grid;place-items:center;min-height:38px;border-radius:7px;background:#101827;color:#dcecff;font-size:11px;font-weight:900}
.metric{font-size:34px;font-weight:950;margin-bottom:4px}
.small,.muted{font-size:12px;color:var(--muted);line-height:1.45}
.pill{display:inline-flex;border:1px solid #324765;border-radius:999px;padding:5px 8px;color:#cfe4ff;font-size:12px;font-weight:800}
.comp-top,.match-top,.status{display:flex;justify-content:space-between;gap:12px}
.name{font-weight:930}
.tier,.priority{color:var(--green);font-weight:950}
.comp-name{color:var(--cyan);font-weight:900;font-size:12px}
.time{color:var(--gold);font-weight:950}
.teams{display:grid;gap:7px;margin:8px 0}
.team{display:flex;align-items:center;gap:9px}
.crest{width:34px;height:34px;min-width:34px;border-radius:8px;display:grid;place-items:center;background:#17243a;border:1px solid #2b405f;font-weight:950;overflow:hidden}
.crest img{width:100%;height:100%;object-fit:contain;padding:3px}
.empty{border:1px dashed #33445f;border-radius:8px;padding:18px;color:var(--muted)}
.form-grid{display:grid;grid-template-columns:1.2fr .8fr;gap:14px}
.field{display:grid;gap:6px;margin-bottom:10px}
label{font-size:12px;color:var(--muted);font-weight:850}
input,textarea{width:100%;border:1px solid #33445f;background:#070d18;color:var(--txt);border-radius:8px;padding:10px;font-family:inherit}
select{width:100%;border:1px solid #33445f;background:#070d18;color:var(--txt);border-radius:8px;padding:10px;font-family:inherit}
textarea{min-height:230px;font-family:Consolas,monospace;font-size:13px}
.import-row{border-top:1px solid #223149;padding-top:10px;margin-top:10px}
.ok{color:var(--green);font-weight:950}
.bad{color:var(--bad);font-weight:950}
.auth-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(250px,.55fr);gap:14px;align-items:start}
.auth-card{min-height:auto}
.auth-side{min-height:auto}
.notice{border:1px solid #33445f;background:#111f31;border-radius:8px;padding:10px;color:#cfe4ff;font-size:13px;line-height:1.4}
.notice.danger{border-color:#7c2940;background:#2a111b;color:#ffd1dc}
.user-row{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:12px;align-items:center}
.inline-form{display:grid;grid-template-columns:1fr;gap:7px}
@media(max-width:900px){.app-hero,.client-hero,.two-col{grid-template-columns:1fr}.quick-actions{grid-template-columns:repeat(2,minmax(118px,1fr))}.live-strip{grid-template-columns:repeat(2,1fr)}}
@media(max-width:760px){.nav{display:none}.bottom-nav{display:grid}.section-head,.comp-top,.match-top{display:block}.form-grid,.auth-grid,.user-row{grid-template-columns:1fr}.quick-actions{grid-template-columns:1fr 1fr}.quick{min-height:54px;touch-action:manipulation}.quick strong{font-size:20px}.card,.list-row,.btn,button{transition:transform .16s ease,border-color .16s ease}.card:active,.list-row:active,.quick:active,.btn:active,button:active{transform:scale(.985)}}
